sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // =====================================================
    // GET REQUEST TYPE FROM VISA CASE
    // =====================================================

    var requestType = "";

    // New request form stores the selected value here
    if (current.isValidField("request_category")) {
        requestType = current.getValue("request_category");
    }

    // Fallback in case an older case uses case_type
    if (!requestType && current.isValidField("case_type")) {
        requestType = current.getValue("case_type");
    }

    if (!requestType) {
        gs.warn(
            "VisaGuardian: No request type found for case " +
            current.getDisplayValue("number")
        );

        return;
    }


    // =====================================================
    // FIND REQUEST TYPE CONFIGURATION
    // =====================================================

    var config = new GlideRecord(
        "x_snc_visaguardi_0_request_type_configuration"
    );

    config.addQuery(
        "request_type",
        requestType
    );

    config.addQuery(
        "active",
        true
    );

    config.setLimit(1);
    config.query();


    // =====================================================
    // CONFIGURATION NOT FOUND
    // =====================================================

    if (!config.next()) {

        gs.warn(
            "VisaGuardian: No active Request Type Configuration found for: " +
            requestType
        );

        return;
    }


    // =====================================================
    // GET DEFAULT DUE DAYS
    // =====================================================

    var dueDays = parseInt(
        config.getValue("default_due_dates"),
        10
    );


    if (isNaN(dueDays) || dueDays < 0) {

        gs.warn(
            "VisaGuardian: Invalid Default Due Dates for request type: " +
            requestType
        );

        return;
    }


    // =====================================================
    // CALCULATE DUE DATE
    // =====================================================

    var dueDate = new GlideDateTime();

    dueDate.addDaysLocalTime(dueDays);


    // =====================================================
    // SET VISA CASE DUE DATE
    // =====================================================

    if (current.isValidField("due_date")) {

        current.setValue(
            "due_date",
            dueDate
        );

    } else {

        gs.warn(
            "VisaGuardian: due_date field does not exist on Visa Case table."
        );

        return;
    }


    // =====================================================
    // LOG FOR TESTING
    // =====================================================

    gs.info(
        "VisaGuardian: Due date calculated for " +
        requestType +
        " | Days: " +
        dueDays +
        " | Due Date: " +
        dueDate.getDisplayValue()
    );

})(current, previous);
